--
-- Table structure for table `doc_content_chunk`
--

DROP TABLE IF EXISTS `doc_content_chunk`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `doc_content_chunk` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '内容块ID',
  `document_id` bigint NOT NULL COMMENT '文档ID',
  `version_number` int DEFAULT '1' COMMENT '版本号',
  `chunk_index` int NOT NULL COMMENT '块索引',
  `content_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '内容类型: TEXT, TABLE, FORMULA, IMAGE, TITLE, ABSTRACT',
  `content_text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '文本内容',
  `original_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '原始内容（用于表格、公式等）',
  `similarity_score` decimal(5,4) DEFAULT '0.0000' COMMENT '相似度得分',
  `ai_probability` decimal(5,4) DEFAULT '0.0000' COMMENT 'AI生成概率',
  `matched_documents` json DEFAULT NULL COMMENT '匹配的文档信息',
  `page_number` int DEFAULT NULL COMMENT '所在页码',
  `section_title` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '章节标题',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '块标题',
  `order_index` int DEFAULT '0' COMMENT '顺序索引',
  `preview_text` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预览文本',
  PRIMARY KEY (`id`),
  KEY `idx_document_id` (`document_id`),
  KEY `idx_content_type` (`content_type`),
  KEY `idx_similarity` (`similarity_score`),
  KEY `idx_doc_version` (`document_id`,`version_number`),
  KEY `idx_order_index` (`order_index`),
  FULLTEXT KEY `idx_chunk_content` (`content_text`),
  CONSTRAINT `doc_content_chunk_ibfk_1` FOREIGN KEY (`document_id`) REFERENCES `doc_document` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3470 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文档内容分块表';
/*!40101 SET character_set_client = @saved_cs_client */;

