DROP TABLE IF EXISTS `doc_kg_mapping`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `doc_kg_mapping` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '映射ID',
  `document_id` bigint NOT NULL COMMENT '文档ID',
  `node_id` bigint NOT NULL COMMENT '图谱节点ID',
  `relevance` decimal(5,4) DEFAULT '1.0000' COMMENT '关联度',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_doc_node` (`document_id`,`node_id`),
  KEY `idx_document_id` (`document_id`),
  KEY `idx_node_id` (`node_id`),
  CONSTRAINT `doc_kg_mapping_ibfk_1` FOREIGN KEY (`document_id`) REFERENCES `doc_document` (`id`) ON DELETE CASCADE,
  CONSTRAINT `doc_kg_mapping_ibfk_2` FOREIGN KEY (`node_id`) REFERENCES `kg_node` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3541 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文档-知识图谱映射表';
/*!40101 SET character_set_client = @saved_cs_client */;

