--
-- Table structure for table `doc_similarity`
--

DROP TABLE IF EXISTS `doc_similarity`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `doc_similarity` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '关联ID',
  `source_doc_id` bigint NOT NULL COMMENT '源文档ID',
  `target_doc_id` bigint NOT NULL COMMENT '目标文档ID',
  `similarity_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '相似类型: OVERALL, TEXT, STRUCTURE, TOPIC',
  `similarity_score` decimal(5,4) NOT NULL COMMENT '相似度得分',
  `matched_chunks` json DEFAULT NULL COMMENT '匹配的内容块信息',
  `algorithm_used` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '使用的算法',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_doc_similarity` (`source_doc_id`,`target_doc_id`,`similarity_type`),
  KEY `idx_source_doc` (`source_doc_id`),
  KEY `idx_target_doc` (`target_doc_id`),
  KEY `idx_similarity_score` (`similarity_score`),
  CONSTRAINT `doc_similarity_ibfk_1` FOREIGN KEY (`source_doc_id`) REFERENCES `doc_document` (`id`),
  CONSTRAINT `doc_similarity_ibfk_2` FOREIGN KEY (`target_doc_id`) REFERENCES `doc_document` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1374 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文档相似度关联表';
/*!40101 SET character_set_client = @saved_cs_client */;

