--
-- Table structure for table `doc_topic`
--

DROP TABLE IF EXISTS `doc_topic`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `doc_topic` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主题ID',
  `document_id` bigint NOT NULL COMMENT '文档ID',
  `version_number` int DEFAULT '1' COMMENT '版本号',
  `topic_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主题类型: KEYWORD, ENTITY, CONCEPT',
  `topic_value` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主题值',
  `confidence` decimal(5,4) DEFAULT '1.0000' COMMENT '置信度',
  `weight` decimal(5,4) DEFAULT '1.0000' COMMENT '权重',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_document_id` (`document_id`),
  KEY `idx_topic_value` (`topic_value`),
  KEY `idx_topic_type` (`topic_type`),
  KEY `idx_doc_version` (`document_id`,`version_number`),
  CONSTRAINT `doc_topic_ibfk_1` FOREIGN KEY (`document_id`) REFERENCES `doc_document` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=681 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文档主题表';
/*!40101 SET character_set_client = @saved_cs_client */;

