--
-- Table structure for table `kg_relation`
--

DROP TABLE IF EXISTS `kg_relation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kg_relation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '关系ID',
  `source_node_id` bigint NOT NULL COMMENT '源节点ID',
  `target_node_id` bigint NOT NULL COMMENT '目标节点ID',
  `relation_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关系类型',
  `weight` decimal(5,4) DEFAULT '1.0000' COMMENT '关系权重',
  `metadata` json DEFAULT NULL COMMENT '关系元数据',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_source_node` (`source_node_id`),
  KEY `idx_target_node` (`target_node_id`),
  KEY `idx_relation_type` (`relation_type`),
  CONSTRAINT `kg_relation_ibfk_1` FOREIGN KEY (`source_node_id`) REFERENCES `kg_node` (`id`),
  CONSTRAINT `kg_relation_ibfk_2` FOREIGN KEY (`target_node_id`) REFERENCES `kg_node` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=370 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='知识图谱关系表';
/*!40101 SET character_set_client = @saved_cs_client */;

