  CONSTRAINT `user_behavior_ibfk_2` FOREIGN KEY (`document_id`) REFERENCES `doc_document` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=621 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户行为分析表';
